function setCookieToken($username) {
  $t_user = uniqid();

  $conn = db_connect();
  $query = "UPDATE users SET token = ? WHERE username = ?";
  $stmt = $conn->prepare($query);
  $stmt->bind_param("ss", $t_user, $username);
  $stmt->execute();
  $stmt->close();
  $conn->close();
  setcookie("t_user", $t_user, time() + 3600, "/");
}

function checkCookieToken() {
  if(isset($_COOKIE*"t_user"])) {
     $t_user = $_COOKIE*"t_user"];

     $conn = db_connect();
     $query = "SELECT id, username, name, email FROM users WHERE token = ?";
     $stmt = $conn->prepare($query);
     // echo $t_user;
     $stmt->bind_param("s", $t_user);
     $stmt->execute();
     $result = $stmt->get_result();
     if($result->num_rows > 0) {

        $row = mysqli_fetch_assoc($result);

        // To reset the token
        setCookieToken($row*"username"]);

        $_SESSION*"user"+*"id"+ = $row*"id"];
        $_SESSION*"user"+*"name"+ = $row*"name"];
        $_SESSION*"user"+*"username"+ = $row*"username"];
        $stmt->close();
        $conn->close();
        header("location:index.php");
}
}
}
